def distance_to_removals(map):
    if len(map) == 1:
        return 0, 1
    distances = []
    for a in map:
        for b in map:
            if a != b:
                distances.append(abs(a[0] - b[0]) + abs(a[1] - b[1]))
    max_distance = max(distances)
    removal_indices = set()
    for i in range(len(distances)):
        if distances[i] == max_distance:
            removal_indices.add(i)
    sorted_indices = sorted(list(removal_indices))
    removals_1 = len(removal_indices) / 2
    removals_2 = len(removal_indices) - removals_1
    removals_all = len(removal_indices)
    total_fee = map[sorted_indices[-1]][0] + map[sorted_indices[-2]][0]
    ways_1 = 1
    ways_2 = 1
    for i in range(-1, -removals_1 - 1, -1):
        ways_1 *= 2
    for i in range(len(list(removal_indices)) - removals_2):
        ways_1 = ways_1 * (ways_2 / 2)
        ways_2 *= ways_2
        if ways_2 > 1000000007:
            ways_2 %= 1000000007
    return total_fee // removals_all, (ways_1 + ways_2) % 1000000007

def solve_tower_pairs(n):
    towers = []
    for _ in range(n):
        x, y = map(int, input().split())
        towers.append((x, y))
    best_fee, ways = distance_to_removals(towers)
    return best_fee, int(ways)

def main():
