from collections import defaultdict, deque

def find_ancestor(a, b, graph):
    parents = defaultdict(int)
    stack = deque([a])
    while len(stack):
        node = stack[-1]
        if node in graph:
            child = graph[node].pop()
            if child != a:
                stack.append(child)
                continue
        while len(stack):
            node = stack.pop()
            parents[node] = parents[graph[node].pop()]
    stack = deque([b])
    while len(stack):
        node = stack[-1]
        if node in parents:
            return node
