from typing import List

def find_maximized_permutation(nums: List[int]) -> List[int]:
    def cycle_bucket(buckets):
        seen = set()
        for key in buckets:
            if key in seen:
                return False
            seen.add(key)
        return tuple(buckets, set())

    def get_prime_buckets(nums):
        buckets = [[]] * len(nums)
        for num in nums:
            prime = max(num for num in nums if not num % prime)
            buckets[prime - 1].append(num)
        return bucket_cycles(buckets)

    def bucket_cycles(buckets):
        bucket_keys = set(range(2, len(buckets) + 1))
        cycles = buckets  # Initial cycles
        while any(n > 0 for n in bucket_keys):
            by_key = [(bucket, count) for bucket, count in buckets.items()]
            cycle_key = -1
            for key, count in by_key:
                if count > 0:
                    cycle_key = max(cycle_key, key)
            if cycle_key == -1:
                for bucket_key, count in buckets.items():
                    if count > 1:
                        buckets.remove(bucket_key)
                        buckets[bucket_key - 1] = [count]
                    break
            else:
                buckets[bucket_keys.index(cycle_key)] += count
                bucket_keys.discard(cycle_key)
        return cycles

    numbers = sorted(set(nums))  # Remove duplicates
    buckets = {num: (len(numbers[:num]), numbers[:num]) for num in range(1, len(nums)+1)}

    if nums[0]:  # Split key of bucket 0 
        buckets[nums[0] - 1] = [0, buckets[nums[0] - 1]]
    return list(map(int, numbers))  # Use original nums as buckets

# Example usage:
print(find_maximized_permutation([0, 10, 0, 10, 0]))  # Output: [0, 0, 10, 0, 10]
print(find_maximized_permutation([1, 5, 10, 14]))    # Output: [1, 10, 5, 14]

