from collections import defaultdict
from math import inf
from typing import List, Tuple

INF = 10**10

def manhattan_distance(x1: int, y1: int, x2: int, y2: int) -> int:
    return abs(x1 - x2) + abs(y1 - y2)

def solve(N: int, towers: List[Tuple[int, int]]) -> Tuple[int, int]:
    # Build a graph: i-th tower has edges to towers that are not in the same army
    adj_graph = defaultdict(list)
    distances = []
    for i in range(N):
        d = [INF] * N
        for j in range(N):
            if i == j:
                continue
            d[j] = manhattan_distance(towers[i][0], towers[i][1], towers[j][0], towers[j][1])
        distances.append(d)
        adj_graph[i] = list(range(N))

    # Dijkstra to find the farthest tower from a given tower
    dp = [[[-1, -1] for _ in range(N)] for _ in range(inf)]
    for i in range(N):
        for j in range(N):
            dist = manhattan_distance(towers[i][0], towers[i][1], towers[j][0], towers[j][1])
            if dp[dist][j][0] != -1:
                dp[dist][i][0] = j
            if dp[dist][j][1] != -1:
                dp[dist][i][1] = j

    # Count how many towers each strategist can manage given their recent fees plus a small constant discount
    semesters = [(dist, i) for i, d in enumerate(distances) if 0 <= d[-1] < inf and d[-1] < INF]
    discounted = [0] * N

    x = semesters.reverse()[-1]
    while dist < x[0] or x[0] == INF:
        prev = (-1, -1)
        val = INF
        for i in range(N):
            if dp[dist+1][i][0] == x[1] or (prev[0] != -1 or prev[0] != dp[dist][i][0]) and dp[dist+1][i][1] == x[0]:
                val = min(val, prev[1] + manhattan_distance(towers[i][0], towers[i][1], prior[0], prior[1]))   
            prev = (dp[dist+2][i][1], val + manhattan_distance(towers[i][0], towers[i][1], prior[0], prior[1]) )
            if x[0] == INF and x[0] % 2 == 1:
                x = (dist, dp[dist][i][0])

    valid_positions = set(zip(*argmax(discounted)))
    return min(x[1], x[0]), len(valid_positions)

N = int(input())
towers = [tuple(map(int, input().split())) for _ in range(N)]
answers = solve(N, towers)
print(*answers)
