import sys
from collections import deque
import math

def calculate_distance(point, center, k):
    x, y = point
    distance = math.sqrt(x**2 + y**2)
    return distance if k <= 1 else distance - math.sqrt(distance**2 - center[0]**2 - center[1]**2)

def is_collinear(point1, point2, point3):
    x1, y1 = point1
    x2, y2 = point2
    x3, y3 = point3
    return (y3 - y1) * (x2 - x1) == (y2 - y1) * (x3 - x1)

def process_input():
    n, k = map(int, input().split())
    points = []
    for _ in range(n):
        x, y = map(int, input().split())
        points.append((x, y))
    return points, k

def find_maximal_sum(points, k):
    total_sum = 0
    collinear_basins = [deque() for _ in range(k + 1)]

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            for z in range(j + 1, len(points)):
                x, y = points[i]
                x2, y2 = points[j]
                x3, y3 = points[z]
                if is_collinear(points[i], points[j], points[z]):
                    total_sum = max(total_sum, calculate_distance(points[i], points[0], k))
                    total_sum = max(total_sum, calculate_distance(points[j], points[0], k))
                    total_sum = max(total_sum, calculate_distance(points[z], points[0], k))

    for i in range(1, k + 1):
        point1 = tuple(points[i - 1])
        point2 = tuple(points[0])
        for j in range(i + 1, k + 1):
            point3 = tuple(points[j - 1])
            total_sum += calculate_distance(point1, point2, i)
            total_sum += calculate_distance(point1, point3, i)
            total_sum += calculate_distance(point2, point3, i)

    return total_sum

if __name__ == "__main__":
    points, k = process_input()
    print(find_maximal_sum(points, k))
