def euclidean_distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def optimal_sum_distances(n, k, bases):
    central_base = None
    for x, y in bases:
        if x == 0 and y == 0:
            central_base = (0, 0)
            break

    distances = []
    for base in bases:
        if central_base:
            if euclidean_distance(base[0], base[1], 0) + euclidean_distance(0, 0, base[0], base[1]) == 2:
                distances.append((base, 0))
        else:
            distances.append(base)

    if central_base:
        remaining_bases = [base for base in bases if base != central_base]
        for i, base1 in enumerate(remaining_bases):
            for base2 in remaining_bases:
                if i != base2:
                    if euclidean_distance(base1[0], base1[1], central_base[0], central_base[1]) + euclidean_distance(central_base[0], central_base[1], base2[0], base2[1]) == 3:
                        distances.append((base1, base2))
                    else:
                        distances.append((base1, base2))

    distances.sort(key=lambda x: (x[0][0], x[0][1]))
    return sum(math.sqrt(x[0] ** 2 + y[0] ** 2) + math.sqrt(x[1] ** 2 + y[1] ** 2) for x, y in distances[:k])

