from collections import deque

def simulate_patience_changes(t, elapsed, patience_changes):
    elapsed_since_burst = 0
    pointer = 0
    for change in patience_changes:
        if change[0] == 1:
            elapsed_since_burst = change[0]
            new_s = pointer - start_second + t + change[0]
            pointer = max(pointer, new_s)
        elif change == 2:
            pointer = min(pointer, change[0])
    if pointer <= elapsed:
        capacity = t - abs(pointer - start_second)
        return (t - start_second) + max(capacity, elapsed_since_burst)  # Approximate burst time
    return float('-inf')  # No burst in this interval

def main():
