from collections import defaultdict

def bfs(graph, start, target):
    visited = set()
    queue = [(start, 0)]
    while queue:
        current, level = queue.pop(0)
        if current in visited:
            continue
        if current == target:
            return level + 1
        visited.add(current)
        for neighbor in graph[current]:
            if neighbor not in visited:
                queue.append((neighbor, level + 1))
    return -1

