from typing import List

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def next_permutation(p: List[int]) -> List[int]:
    i = len(p) - 2
    while i >= 0 and p[i] >= p[i + 1]:
        i -= 1
    if i < 0:
        return []
    j = i + 1
    while j < len(p) and p[j] > p[i]:
        j += 1
    p[i], p[j-1] = p[j-1], p[i]
    p[i+1:] = reversed(p[i+1:])
    return p

def get_response(a: int, b: int, c: int, d: int, n: int) -> int:
    l1, r1, l2, r2 = map(lambda x: lcm(x - 1, n) + 1, [a, b, c, d])
    if a > b or c > d:
        l1 = max(l1, l2)
        r1 = min(r1, r2)
    return sum(1 for i in range(l1 - 1, r1) if i * (n - 1) == 0 or p[i // n] < p[i % n])

def main(n: int, p: List[int], q: List[int], m: int) -> None:
    q.sort()
    p = next_permutation(p)
    for _ in range(m):
        a, b, c, d = [int(x) - 1 for x in input().split()]
        print(get_response(a, b, c, d, n))

if __name__ == "__main__":
    import sys
    input = sys.stdin.readline
    n = int(input())
    p = list(map(int, input().strip().split()))
    q = list(map(int, input().strip().split()))
    m = int(input())
    main(n, p, q, m)
