import math

def max_radius(n, centers):
    centers.sort()
    max_radius = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                d = max_centers_to_middle_step_one(centers[i], centers[j], centers[k])
                max_radius = max(max_radius, d / 2)
    return max_radius

def max_centers_to_middle_step_one(center1, center2, center3):
    d1 = math.sqrt((center1[0] - center2[0])**2 + (center1[1] - center2[1])**2)
    d2 = math.sqrt((center1[0] - center3[0])**2 + (center1[1] - center3[1])**2)
    d3 = math.sqrt((center2[0] - center3[0])**2 + (center2[1] - center3[1])**2)
    if d1 <= d2 + d3 and d2 <= d3 + d1 and d3 <= d1 + d2:
        return d1
    elif d1 <= d3 + d2 and d3 <= d2 + d1 and d2 <= d1 + d3:
        return d2
    else:
        return d3

