    total_distances.sort(reverse=True)

    optimal_solutions = []
    for i in range(len(total_distances)):
        if i + 1 > n - k:
            break
        for j in range(i + 1, i + n - k + 1):
            new_distance = total_distances[i] + total_distances[j]
            if new_distance not in optimal_solutions and new_distance <= 10**10:
