# Record the visited and placed positions of the bees and Nastya
visited = {1: False, 2: False, 3: False, 4: False, 5: False}
placed_positions = {1: 1, 2: 5, 3: 3, 4: 5, 5: 1}

def neighbours(v):
    """Return all unvisited neighbours of v."""
    return [u for u in range(1, 6) if v != u and not visited[u]]

def move(placed_positions):
    """Simulate one move according to current statistics and rates."""
    actions = []
    for v in range(1, 6):
        if neighbours(v) and placed_positions[v]:
            actions.append((v, v))
        else:
            if visited[v] and not placed_positions[v]:
                actions.append((v, placed_positions[v]))
    return actions

def simulate_moves(placed_positions):
    """Simulate the game up to and including the Nastya's move or up to 5 moves."""
    steps = 0
    while True:
        actions = move(placed_positions)
        for v, u in set(actions).difference(placed_positions.keys()):
            placed_positions[v] = visited[placed_positions[v]] = u
            visited[placed_positions[v]] = True
        steps += 1

        if steps == 6:
            return True
        elif actions == []:
            return False

def reveal_move(placed_positions):
    """Reveal the move according to the given placed_positions."""
    v = placed_positions[1]
    u = placed_positions[5]
    return [v, v, v] if v == u else [v, v]

if simulate_moves(placed_positions):
    # Replay the revealed move on the player side
    move(reveal_move(placed_positions))
