def count_distinct_arrays():
    # Read the input values
    n, q = map(int, input().split())
    queries = [tuple(map(int, input().split())) for _ in range(q)]

    # Create a set of unique results
    unique_results = set()
    for start, end in queries:
        mask = 1 << (start - 1)
        for i in range(start, end + 1):
            mask |= 1 << (i - 1)
        for mask_start in range(2 ** (n - 1)):
            mask_result = sum((mask_start >> ((end - 1) - i) & 1) & 1
                              for i in range(max(0, start - (n - 2)), min(n, end + 1)))
            if mask_result not in unique_results:
                unique_results.add(mask_result)

    # Output the number of unique results modulo 998244353
    print(len(unique_results) % 998244353)

